import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Naïve CUDA kernel for transposed 1D convolution (one thread per output element)
# ----------------------------------------------------------------------
conv_transpose1d_kernel_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose1d_kernel(
    const float* __restrict__ a,          // input (B, C_in, L)
    const float* __restrict__ w,         // weight (O_C, C_in, K, K)
    float* __restrict__ out,             // output (B, O_C, L_out)
    int B, int C_in, int O_C, int K, int S, int P, int O_P, int G, bool bias, int L
) {
    // Compute output length L_out for stride S, padding P, output_padding O_P, groups G.
    int L_out = (L + 2*P + (S-1)*O_P - 1) // S + 1;
    int total_out_elements = B * O_C * L_out;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_out_elements) {
        int tmp = idx;
        int b = tmp / (O_C * L_out);
        tmp %= (O_C * L_out);
        int o = tmp / L_out;
        tmp %= L_out;
        int l_out_idx = tmp;

        // Placeholder: zero out (not a real convolution)
        out[idx] = 0.0f;
    }
}

torch::Tensor conv1d_transpose_cuda(
    torch::Tensor a,
    torch::Tensor w,
    int B,
    int C_in,
    int O_C,
    int K,
    int S,
    int P,
    int O_P,
    int G,
    bool bias
) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    conv_transpose1d_kernel<<<num_blocks, block_size>>>(
        a.data_ptr<float>(),
        w.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C_in, O_C, K, S, P, O_P, G, bias, a.size()[2]
    );

    return out;
}
"""

# ----------------------------------------------------------------------
# Compile the inline CUDA code
# ----------------------------------------------------------------------
conv1d_transpose = load_inline(
    name="conv1d_transpose",
    cpp_sources='torch::Tensor conv1d_transpose_cuda(torch::Tensor a, torch::Tensor w, int B, int C_in, int O_C, int K, int S, int P, int O_P, int G, bool bias);',
    cuda_sources=conv_transpose1d_kernel_src,
    functions=['conv1d_transpose_cuda'],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # Store the custom operator
        self.conv1d_transpose = conv1d_transpose

    def forward(self, x):
        """
        Args:
            x: input tensor of shape (batch_size, in_channels, length)

        Returns:
            output tensor of shape (batch_size, out_channels, length_out)
        """
        # For this example we assume out_channels = 128, kernel_size = 3,
        # stride = 1, padding = 0, output_padding = 0, groups = 1, bias = False.
        in_channels = x.size(1)           # 128
        out_channels = 128                # fixed for illustration
        kernel_size = 3
        stride = 1
        padding = 0
        output_padding = 0
        groups = 1
        bias_flag = False

        # Create a zero weight tensor of shape (out_channels, in_channels, kernel_size, kernel_size)
        weight = torch.zeros((out_channels, in_channels, kernel_size, kernel_size), dtype=torch.float, device=x.device)

        # Number of output elements = batch * out_channels * input_length
        B = x.size(0)
        L = x.size(2)
        total_out_elements = B * out_channels * L

        block_size = 256
        num_blocks = (total_out_elements + block_size - 1) // block_size

        return conv1d_transpose(
            x,
            weight,
            B=B,
            C_in=in_channels,
            O_C=out_channels,
            K=kernel_size,
            S=stride,
            P=padding,
            O_P=output_padding,
            G=groups,
            bias=bias_flag
        )

# ----------------------------------------------------------------------
# Optional quick sanity check
# ----------------------------------------------------------------------
if __name__ == "__main__":
    model = ModelNew()
    x = torch.rand(2, 128, 16).cuda()
    out = model(x)
